INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(127277, 'ruRU', '', 'Этот раунд за счёт $n! Бесплатные напитки следующие две минуты!', 24330),
(127295, 'ruRU', '', 'Я прошёл через это испытание тысячи раз. И каждый раз я показывал Одину, что его воины не достойны выйти против меня на ринг.', 24330),
(127296, 'ruRU', '', 'Ты глуп, $r. Но если смерть - это то, что нужно тебе, чтобы выучить урок, пусть так и будет.', 24330),
(127297, 'ruRU', '', 'Я НЕ СКЛОНЮСЬ ПЕРЕД ТАКИМИ, КАК ТЫ, ПРОСТОЛЮДИН!', 24330),
(127300, 'ruRU', '', 'Давно мой клинок не пробовал крови. Интересно, понравится ли ему твоя...', 24330),
(127336, 'ruRU', '', 'Когда я одолею тебя, я буду на шаг ближе к вознесению.', 24330),
(127337, 'ruRU', '', 'Я... не могу поверить, что проиграл. Возможно, я не достоин вознесения...', 24330),
(127351, 'ruRU', '', 'Добро пожаловать на Трактирный обход Киринтора, $n. Угощайся напитками и бесплатной едой, сколько сможешь. Через пару минут мы отправляемся к следующему трактиру.', 24330),
(127362, 'ruRU', '', 'Таких, как ты, очистят от этого мира!', 24330),
(127363, 'ruRU', '', 'Ты сгоришь в силе, которую не способен понять!', 24330),
(127371, 'ruRU', '', 'Наш сегодняшний боец - мощное млекопитающее со вкусом к мести. Он не хочет помогать тебе... он хочет убить тебя. Это враждебный лось, Стражник Скорби!', 24330),
(127372, 'ruRU', '', 'Наш сегодняшний боец - стая задиристых пингвинов с полярных круч Нордскола. Берегись Скользкого Стада!', 24330),
(127373, 'ruRU', '', 'Эти три пандарена бросают тебе вызов... дотащи одну из своих тележек с пивом до середины ринга, прежде чем они дотащат свою. Победившая команда получает право его выпить!', 24330),
(127374, 'ruRU', '', 'Б-Е-Г-Е-М-О-Т означает смерть! Постарайся не быть раздавленным нашим следующим бойцом, Сеньей!', 24330),
(127375, 'ruRU', '', 'Тебе не нужно побеждать этих существ, нужно просто выжить. Ах да, мы также забираем всё твоё снаряжение и опыт. Наслаждайся Пробегом через Тернистую Долину!', 24330),
(127376, 'ruRU', '', 'Если не можешь победить его, присоединяйся к нему! Готовься к тому, что твой разум, лицо и замороженные напитки растопит единственный и неповторимый Разрушитель разума Гззаж!', 24330),
(127377, 'ruRU', '', 'Она уже выросла и готова к бою. Конечно, сейчас она выглядит как милая кошечка, но подожди, пока её не прижмут в угол. Держись подальше от нашего следующего бойца, Мажарин!', 24330),
(127391, 'ruRU', '', 'Мне нравятся твои очки. Такие винтажные.', 24330),
(127392, 'ruRU', '', 'А теперь подождём. Этот бой будет великолепен!', 24330),
(127398, 'ruRU', '', 'Привет, $n. Знаешь ли ты, что сегодня проходит трактирный обход, организованный Киринтором? На самом деле я могу телепортировать тебя в трактир, где все собрались.', 24330),
(127399, 'ruRU', '', 'Теперь, когда Даумир и её выводок наши, перевес скоро сменится!', 24330),
(127400, 'ruRU', '', 'Не пойми меня неправильно... Четыре Всадника весьма впечатляют. Но гигантские драконы-нежить...', 24330),
(127401, 'ruRU', '', 'Когда демоны увидят наш выводок, они могут просто умереть от страха!', 24330),
(127402, 'ruRU', '', 'А если нет, я с радостью разрублю их на куски своим топором. Как бы то ни было, шкура с меня не слезет!', 24330),
(127403, 'ruRU', '', '...Если бы на моей спине осталась хоть какая-то шкура, конечно.', 24330),
(127406, 'ruRU', '', 'Ты ничтожен передо мной.', 24330),
(127407, 'ruRU', '', 'Лорд Иллидан будет рад твоей смерти!', 24330),
(127408, 'ruRU', '', 'Это будет быстро.', 24330),
(127409, 'ruRU', '', 'Ты утонешь!', 24330),
(127410, 'ruRU', '', 'Тони или плыви!', 24330),
(127411, 'ruRU', '', 'Ты уверен, что тебе нужна моя помощь?', 24330),
(127412, 'ruRU', '', 'Убийца. Полагаю, у меня есть время помочь тебе.', 24330),
(127413, 'ruRU', '', 'Может, займёмся чем-то более интересным на этот раз?', 24330),
(127414, 'ruRU', '', 'Бойся Коилскар!', 24330),
(127415, 'ruRU', '', 'Ты мне наскучил.', 24330),
(127416, 'ruRU', '', 'Тебе следовало научиться плавать.', 24330),
(127417, 'ruRU', '', 'Пища для рыб!', 24330),
(127419, 'ruRU', '', 'Коилскар всегда добивается своего.', 24330),
(127421, 'ruRU', '', 'Это не... возможно...', 24330),
(127422, 'ruRU', '', 'Тебе придётся сделать это... без меня...', 24330);
